def apply_discounts(price_cents, codes):
    best_pct = 0
    flats = 0
    for code in codes:
        if code.startswith("PCT") and code[3:].isdigit():
            best_pct = max(best_pct, int(code[3:]))
        elif code.startswith("FLAT") and code[4:].isdigit():
            flats += int(code[4:])
    price = price_cents - (price_cents * best_pct) // 100
    price -= flats
    return max(price, 0)
